import sys,json,datetime
from pathlib import Path
from playwright.sync_api import sync_playwright
base,out,src,dst=sys.argv[1:];out=Path(out);rows=[];uids={'admin':1,'alice':2,'bob':3,'other':4}
with sync_playwright() as p:
 b=p.chromium.launch(headless=True);c=b.new_context();page=c.new_page();page.clock.install(time=datetime.datetime.fromisoformat('2030-04-10T09:00:00+08:00'));page.goto(base)
 for email in ['nonexistent@meetspace.test',src+'@meetspace.test']:
  page.locator('#login-form [name=email]').fill(email);page.locator('#login-form [name=password]').fill('wrong-synthetic');page.locator('#login-form button[type=submit]').click();page.get_by_text('邮箱或密码不正确',exact=True).wait_for();rows.append({'wrong-login-feedback':'邮箱或密码不正确','account':email})
 page.locator('[data-account='+src+']').click();page.locator('#login-form button[type=submit]').click();page.locator('[data-logout]').first.wait_for();old=c.cookies()[0]['value'];r=c.request.post(base+'/api/login',data={'email':dst+'@meetspace.test','password':'MeetSpace!2026'},headers={'X-Meeting-App':'1','Origin':base});assert r.status==200;attrs=r.headers['set-cookie'];assert all(x in attrs for x in ['HttpOnly','SameSite=Lax','Path=/']);new=c.cookies()[0];assert new['httpOnly'] and new['sameSite']=='Lax' and new['path']=='/';assert old!=new['value'];assert 'meetspace_session' not in page.evaluate('document.cookie');page.evaluate("history.pushState({},'', '/same-origin-subpath')");assert 'meetspace_session' not in page.evaluate('document.cookie');identity=c.request.get(base+'/api/session').json();assert identity['user']['id']==uids[dst];page.goto(base);page.locator('[data-logout]').first.wait_for();page.screenshot(path=str(out/(src+'-'+dst+'.png')),full_page=True);page.locator('[data-logout]').first.click();page.locator('#login-form').wait_for();assert not c.cookies();page.reload();page.locator('#login-form').wait_for();rows.append({'switch':[src,dst],'identity':identity,'cookie_attributes_valid':True,'root_and_subpath_httpOnly':True,'logout_removed':True});b.close()
(out/(src+'-'+dst+'.json')).write_text(json.dumps(rows,ensure_ascii=False,indent=2));print('UI errors, switch cookies, subpath, new identity and logout passed')
